	String makeQueryString() {
		String queryString = null;
		if (queryVariant == QueryVariant.IDS) {
			GraphPattern whereClause = getWhereClause();
			queryString = Queries.SELECT(getInnerProjection())
					.distinct()
					.where(whereClause)
					.getQueryString();
		} else if (queryVariant == QueryVariant.ENTITIES) {
			// Caution: in this case, we want to match the entity pattern using the bindings for the
			// _targetEntity
			// variable, but if the sub-select returns an unbound _targetEntity, those patterns
			// would match
			// every such entity in the database. Therefore, we use the targetOpt variable in an
			// OPTIONAL pattern. The
			// targetOpt variable is bound to _targetEntity or to <nothing:found_[someRandomTag]> if
			// _targetEntity is unbound,
			// so in that case the targetEntityPattern will match nothing
			Variable targetOpt = var("targetOpt");
			Projectable[] innerProjection = appendProjectable(
					getInnerProjection(),
					as(
							iff(
									bound(JoinQuery._targetEntity),
									JoinQuery._targetEntity,
									NOTHING),
							targetOpt));
			GraphPattern entityQuery = select(innerProjection).distinct().where(getWhereClause());
			GraphPattern targetPattern = this.targetEntityPattern.apply(targetOpt);
			if (targetPattern != null) {
				entityQuery = entityQuery.and(targetPattern.optional());
			}
			queryString = Queries.SELECT(getOuterProjection())
				.distinct()
				.where(entityQuery)
				.getQueryString();
		} else {
			queryString = Queries.SELECT(getOuterProjection())
					.where(select(getInnerProjection()).distinct().where(getWhereClause()))
					.groupBy(getGroupBy())
					.getQueryString();
		}
		if (logger.isDebugEnabled()) {
			logger.debug("Generated query string: \n {}", queryString);
		}
		return queryString;
	}

	private Projectable[] appendProjectable(Projectable[] arr, Projectable toAppend) {
		Projectable[] combined = new Projectable[arr.length + 1];
		combined[arr.length] = toAppend;
		System.arraycopy(arr, 0, combined, 0, arr.length);
		return combined;
	}

	private Groupable[] getGroupBy() {
		List<Groupable> groupables = new ArrayList<>();
		if (this.queryVariant == QueryVariant.COUNT) {
			if (this.contextIdVariable != null) {
				groupables.add(contextIdVariable);
			}
			groupables.add(JoinQuery._sourceEntity);
			if (this.groupVariable != null) {
				groupables.add(this.groupVariable);
			}
		}
		return groupables.toArray(new Groupable[0]);
	}

	static Projectable[] addRequiredTargetProjection(Projectable[] projections) {
		List<Projectable> result = new ArrayList<>();
		result.add(JoinQuery._targetEntity);
		if (projections != null) {
			for (Projectable projection : projections) {
				if (!(projection instanceof Variable variable)
						|| !variable.getVarName().equals(JoinQuery._targetEntity.getVarName())) {
					result.add(projection);
				}
			}
		}
		return result.toArray(new Projectable[0]);
	}

	private Projectable[] getOuterProjection() {
		if (this.queryVariant == QueryVariant.IDS) {
			return null;
		}
		ArrayList<Projectable> projectables = new ArrayList<>();
		if (this.contextIdVariable != null) {
			projectables.add(this.contextIdVariable);
		}

		if (this.queryVariant == QueryVariant.ENTITIES) {
			Projectable[] entityProjection = addRequiredTargetProjection(
					this.projection.apply(JoinQuery._targetEntity));
			projectables.add(JoinQuery._sourceEntity);
			projectables.addAll(Arrays.asList(entityProjection));
		} else if (this.queryVariant == QueryVariant.COUNT) {
			if (this.groupVariable != null) {
				projectables.add(JoinQuery._sourceEntity);
				projectables.add(this.groupVariable);
				projectables.add(as(Expressions.count(JoinQuery._targetEntity), JoinQuery._count));
			} else {
				projectables.add(JoinQuery._sourceEntity);
				projectables.add(as(Expressions.count(JoinQuery._targetEntity), JoinQuery._count));
			}
		} else {
			throw new IllegalStateException("QueryVariant " + this.queryVariant + " not supported");
		}
		return projectables.toArray(new Projectable[0]);
	}

	private Projectable[] getInnerProjection() {
		List<Projectable> projectables = new ArrayList<>();
		if (this.contextIdVariable != null) {
			projectables.add(this.contextIdVariable);
		}
		if (this.queryVariant == QueryVariant.IDS) {
			projectables.add(JoinQuery._sourceEntity);
			projectables.add(JoinQuery._targetEntity);
		} else if (this.queryVariant == QueryVariant.ENTITIES) {
			projectables.add(JoinQuery._sourceEntity);
			projectables.add(JoinQuery._targetEntity);
		} else if (this.queryVariant == QueryVariant.COUNT) {
			if (this.groupVariable != null) {
				projectables.add(JoinQuery._sourceEntity);
				projectables.add(this.groupVariable);
				projectables.add(JoinQuery._targetEntity);
			} else {
				projectables.add(JoinQuery._sourceEntity);
				projectables.add(JoinQuery._targetEntity);
			}
		} else {
			throw new IllegalStateException("QueryVariant " + this.queryVariant + " not supported");
		}
		return projectables.toArray(new Projectable[0]);
	}

	private GraphPattern andIfPresent(GraphPattern leftOrNull, GraphPattern rightOrNull) {
		if (rightOrNull == null) {
			return leftOrNull;
		}
		if (leftOrNull == null) {
			if (rightOrNull == null) {
				throw new UnsupportedOperationException("left or right parameter must be non-null");
			}
			return rightOrNull;
		}
		return leftOrNull.and(rightOrNull);
	}

	private GraphPattern optionalIfPresent(GraphPattern patternOrNull) {
		if (patternOrNull == null) {
			return null;
		}
		return patternOrNull.optional();
	}

	private GraphPattern getWhereClause() {
		GraphPattern relation = andIfPresent(
				JoinQuery._sourceEntity.has(predicate, JoinQuery._targetEntity),
				this.relationConstraints.apply(
						JoinQuery._sourceEntity, JoinQuery._targetEntity));
		return switch (this.joinType) {
		case INNER -> andIfPresent(
				andIfPresent(
						andIfPresent(
								relation,
								this.sourceEntityConstraints.apply(
										JoinQuery._sourceEntity)),
						this.targetEntityConstraints.apply(JoinQuery._targetEntity)),
				this.valuesClause);
		case LEFT_OUTER -> andIfPresent(
				andIfPresent(
						this.sourceEntityConstraints.apply(JoinQuery._sourceEntity),
						andIfPresent(
								relation,
								this.targetEntityConstraints.apply(
										JoinQuery._targetEntity))
												.optional()),
				this.valuesClause);
		case RIGHT_OUTER -> andIfPresent(
				andIfPresent(
						this.targetEntityConstraints.apply(JoinQuery._targetEntity),
						andIfPresent(
								relation,
								this.sourceEntityConstraints.apply(
										JoinQuery._sourceEntity))
												.optional()),
				this.valuesClause);
		};
	}
